    if (MAP_SCAN < MAP_N) mp_cursor = (mp_cursor + kk) % MAP_N; else
    mp_cursor = (mp_cursor + budget * 3 + 1) % MAP_N;
    if (MAP_DBG && (frame_no % 200) == 0) fprintf(stderr, "MAP f=%d tries=%ld match=%ld acc=%ld\n", frame_no, mp_tries, mp_match, mp_acc);
