    for(int k=0;k<m;k++){double A[8];aj_eval(&L,type,e1,e2,Rwc[k],pwc[k],&o,k,A,4,0);aj_check(Hl+8*k,A,4,NP,4+type);}
#endif
#endif
    memset(Hx, 0, nr * MAXD * sizeof(double));
