                if (a < 3) { double w[3] = {0, 0, 0}; w[a] = ee; rot_right(cp.R, w); } else cp.p[a - 3] += ee;
                camera_pose(&cp, Rp, pp);
                lres(&L, Rp, pp, o.x[k], o.y[k], o.enx[k], o.eny[k], o.ehl[k], sg ? hm : hp);
