        for (int i = c; i < nr; i++) v[i] = Hl[i * 4 + c];
        v[c] -= alpha;
        for (int i = c; i < nr; i++) vn += v[i] * v[i];
        if (vn < 1e-30) continue;
        for (int j = c; j < NC; j++) {
            double s = 0;
            for (int i = c; i < nr; i++) s += v[i] * Hl[i * 4 + j];
            s *= 2 / vn;
            for (int i = c; i < nr; i++) Hl[i * 4 + j] -= s * v[i];
        }
