#else
        for (int jj = 0; jj < nnz; jj++) {
            int j = nzc[jj]; double s = 0;
            for (int i = c; i < nr; i++) s += v[i] * Hx[i * MAXD + j];
            s *= 2 / vn;
            for (int i = c; i < nr; i++) Hx[i * MAXD + j] -= s * v[i];
        }
#endif
