        if (!VIS4 && DET_PERIOD > 1 && ((cell + frame_no) % DET_PERIOD) != 0) continue; /* approx arm: each empty cell is rescored every DET_PERIOD frames */
        if (DET_COOL && det_until[cell] > frame_no) continue;
